
const plan=[
["Days 1–2","Profile foundation","Set consistent profile photo, bio, location/service description and contact route on Instagram and Facebook. Verify ownership and access."],
["Day 3","Google presence","Claim or review Google Business Profile. Use accurate business details, real photos and correct service information; do not create duplicate listings."],
["Days 4–5","Coach introduction","Record two short videos introducing Subhalaxmi, the centre and the coaching approach. Obtain consent for anyone appearing."],
["Days 6–7","Content batch","Prepare four short videos, two carousels and seven simple story prompts. Add captions and accessibility-friendly text."],
["Days 8–10","Healthy Habits series","Publish three practical habit videos: hydration, balanced meals and daily movement. Keep advice general and evidence-aware."],
["Days 11–12","Community engagement","Ask a simple poll or question. Reply helpfully; avoid unsolicited health assessments in public comments."],
["Days 13–14","First review","Check reach, profile visits, saves, meaningful comments and enquiries. Repeat topics that created genuine interest."],
["Days 15–17","FAQ series","Publish three answers to common questions about coaching, session process and building consistent habits."],
["Days 18–19","Local discovery","Publish a location-aware post and update Google photos/services. Ask satisfied customers for honest reviews without incentives or pressure."],
["Days 20–21","Community challenge","Run a free seven-day healthy-habits challenge. Make participation optional and avoid restrictive diets or outcome promises."],
["Days 22–23","Customer experience","Share an approved, authentic customer experience focused on service and habit-building, not guaranteed body or health outcomes."],
["Days 24–25","Local collaboration","Invite one suitable local educator or community creator for an educational conversation. Disclose any paid or reciprocal arrangement."],
["Days 26–27","Enquiry follow-up","Review the lead list. Follow up only where permission was given; record outcomes and respect opt-outs."],
["Days 28–29","Best-content replay","Repurpose the best-performing topic into a Reel, carousel and story. Do not repost other creators' work without permission."],
["Day 30","Monthly review","Compare publishing, reach, enquiries, qualified enquiries and customers. Choose three improvements for month two."]
];
const $=id=>document.getElementById(id);
function get(k){try{return JSON.parse(localStorage.getItem("shh_"+k)||"[]")}catch(e){return []}}
function set(k,v){localStorage.setItem("shh_"+k,JSON.stringify(v))}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
