function setLanguage(lang){currentLang=lang;document.documentElement.lang=lang==='or'?'or':'en';$('langEn').classList.toggle('langactive',lang==='en');$('langOr').classList.toggle('langactive',lang==='or');document.querySelectorAll('[data-en]').forEach(el=>el.textContent=lang==='or'?(el.dataset.or||el.dataset.en):el.dataset.en);document.querySelectorAll('nav button').forEach(b=>{let en=b.dataset.en||b.textContent.trim();b.dataset.en=en;b.textContent=lang==='or'?(translations[en]||en):en});document.querySelectorAll('h2,h3,label:not(.check),p,li,.muted,.tag,.sub,.brand,.hero').forEach(el=>{if(el.children.length===0&&!el.dataset.original)el.dataset.original=el.textContent;let original=el.dataset.original;if(original){el.textContent=lang==='or'?(translations[original.trim()]||original):original}});localStorage.setItem('shh_language',lang)}
function makeWaDraft(){let lang=$('waLang').value,type=$('waType').value,n=$('waName').value.trim();let en={welcome:`Hello${n?' '+n:''}, thank you for contacting Sai Health Hub. We appreciate your interest. Please let us know what information about our health-coaching sessions you would like.`,follow:`Hello${n?' '+n:''}, this is Sai Health Hub. You had agreed to receive a follow-up from us. Would you still like the information you requested? Reply STOP if you do not want further messages.`,event:`Hello${n?' '+n:''}, Sai Health Hub is inviting you to a free community session on practical healthy daily habits. Participation is optional. Reply if you would like the time and details. Reply STOP to opt out.`,optout:`Thank you. We have noted your request and will not send you further promotional messages from Sai Health Hub.`};let or={welcome:`ନମସ୍କାର${n?' '+n:''}, Sai Health Hub ସହ ଯୋଗାଯୋଗ କରିଥିବାରୁ ଧନ୍ୟବାଦ। ଆମର ସ୍ୱାସ୍ଥ୍ୟ-ପରାମର୍ଶ ସେସନ୍ ବିଷୟରେ କେଉଁ ସୂଚନା ଚାହୁଁଛନ୍ତି ଜଣାନ୍ତୁ।`,follow:`ନମସ୍କାର${n?' '+n:''}, ଏହା Sai Health Hub ରୁ। ଆପଣ ପୂର୍ବରୁ ଫଲୋ-ଅପ୍ ପାଇଁ ସମ୍ମତି ଦେଇଥିଲେ। ଆପଣ ଚାହିଥିବା ସୂଚନା ଏବେ ମଧ୍ୟ ଚାହୁଁଛନ୍ତି କି? ଆଉ ବାର୍ତ୍ତା ନଚାହିଁଲେ STOP ଲେଖନ୍ତୁ।`,event:`ନମସ୍କାର${n?' '+n:''}, Sai Health Hub ପକ୍ଷରୁ ଦୈନନ୍ଦିନ ସୁସ୍ଥ ଅଭ୍ୟାସ ଉପରେ ଏକ ମାଗଣା ସାମୁଦାୟିକ ସେସନ୍ ପାଇଁ ଆମନ୍ତ୍ରଣ। ଯୋଗଦେବା ଇଚ୍ଛାଧୀନ। ସମୟ ଓ ବିବରଣୀ ପାଇଁ ଉତ୍ତର ଦିଅନ୍ତୁ।`,optout:`ଧନ୍ୟବାଦ। ଆପଣଙ୍କ ଅନୁରୋଧ ରେକର୍ଡ କରାଗଲା। Sai Health Hub ପକ୍ଷରୁ ଆପଣଙ୍କୁ ଆଉ ପ୍ରଚାରମୂଳକ ବାର୍ତ୍ତା ପଠାଯିବ ନାହିଁ।`};$('waDraft').value=(lang==='or'?or:en)[type]}
function copyWa(){if($('waType').value!=='optout'&&!$('waConsent').checked){alert('Please confirm the recipient explicitly opted in before copying a promotional/follow-up message.');return}let t=$('waDraft').value;if(!t.trim())return;copyText(t)}
function copyText(t){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(t).then(()=>alert('Copied. Review before sending.'),()=>fallbackCopy(t))}else fallbackCopy(t)}function fallbackCopy(t){let a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();try{document.execCommand('copy');alert('Copied. Review before sending.')}catch(e){alert('Copy unavailable. Select and copy the text manually.')}a.remove()}
function draftLeadWhatsApp(id){let x=get('leads').find(v=>v.id===id);if(!x||x.consent!=='Yes'){alert('No recorded follow-up consent.');return}document.querySelector('[data-tab="whatsapp"]').click();$('waName').value=x.name.split(' ')[0];$('waType').value='follow';makeWaDraft();$('waConsent').checked=true}
function exportBackup(){let keys=['plan','content','leads','metrics','creative','customers','checkins','mediaRefs','idDocs','idReviews','masterProfiles','businessContacts','followups','consultations','consentEvents','qaChecks'];let data={app:'Sai Health Hub Digital Influence Hub',version:'2.0',exportedAt:new Date().toISOString(),data:{}};keys.forEach(k=>data.data[k]=get(k));data.data.language=localStorage.getItem('shh_language')||'en';let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sai-health-hub-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('backupStatus').textContent='Backup created. Store it privately.'}
function importBackup(ev){let f=ev.target.files[0];if(!f)return;let rd=new FileReader();rd.onload=()=>{try{let b=JSON.parse(rd.result);if(!b.data||!['plan','content','leads','metrics'].every(k=>Array.isArray(b.data[k])))throw Error('Invalid backup format');if(!confirm('Restore this backup? Current app records will be replaced.'))return;['plan','content','leads','metrics'].forEach(k=>set(k,b.data[k]));if(Array.isArray(b.data.creative))set('creative',b.data.creative);['customers','checkins','mediaRefs','idDocs','idReviews','masterProfiles','businessContacts','followups','consultations','consentEvents','qaChecks'].forEach(k=>{if(Array.isArray(b.data[k]))set(k,b.data[k])});if(b.data.language)localStorage.setItem('shh_language',b.data.language);renderPlan();renderContent();renderLeads();renderMetrics();renderIdDocs();renderCustomerOptions();renderCustomerProgress();renderMediaList();renderBusinessDesk();renderQAChecks();makeWaDraft();makePoster();setLanguage(localStorage.getItem("shh_language")||"en");$('backupStatus').textContent='Backup restored successfully in this browser.'}catch(e){alert('Could not restore: '+e.message)}finally{ev.target.value=''}};rd.readAsText(f)}
function clearAllData(){if(confirm('Delete ALL Sai Health Hub app records from this browser? Export a backup first if needed.')){['plan','content','leads','metrics','creative','customers','checkins','mediaRefs','idDocs','idReviews','masterProfiles','businessContacts','followups','consultations','consentEvents','qaChecks'].forEach(k=>localStorage.removeItem('shh_'+k));renderPlan();renderContent();renderLeads();renderMetrics();renderIdDocs();renderCustomerOptions();renderCustomerProgress();renderMediaList();renderBusinessDesk();renderQAChecks();makeWaDraft();makePoster();setLanguage(localStorage.getItem("shh_language")||"en");$('backupStatus').textContent='All app data deleted from this browser.'}}
function renderPlan(){let done=get("plan");$("planList").innerHTML=plan.map((p,i)=>`<div class="item"><label class="check"><input type="checkbox" ${done.includes(i)?"checked":""} onchange="togglePlan(${i},this.checked)"><span><b>${p[0]} · ${p[1]}</b><br><span class="muted">${p[2]}</span></span></label></div>`).join("")}
function togglePlan(i,v){let a=get("plan").filter(x=>x!==i);if(v)a.push(i);set("plan",a)}
function addContent(){let a=get("content");a.unshift({id:Date.now(),format:$("format").value,pillar:$("pillar").value,title:$("ctitle").value.trim(),copy:$("ccopy").value.trim(),cta:$("cta").value.trim()});if(!a[0].title&&!a[0].copy){alert("Add a title or script first.");return}set("content",a);$("ctitle").value=$("ccopy").value=$("cta").value="";renderContent()}
function renderContent(){let a=get("content");$("contentList").innerHTML=a.length?a.map(x=>`<div class="item"><span class="pill">${esc(x.format)}</span><b> ${esc(x.title||"Untitled draft")}</b><div class="muted">${esc(x.pillar)}</div><p>${esc(x.copy)}</p><div class="small"><b>CTA:</b> ${esc(x.cta)}</div><button class="btn danger small" onclick="delContent(${x.id})">Delete</button></div>`).join(""):"<p class='muted'>No drafts saved yet.</p>"}
function delContent(id){set("content",get("content").filter(x=>x.id!==id));renderContent()}
function copyDraft(){let t=[$("ctitle").value,$("ccopy").value,"CTA: "+$("cta").value].join("\n\n");copyText(t)}
function addLead(){
 let name=$("lname").value.trim(),phone=$("lcontact").value.trim(),requestedConsent=$("lconsent").value,evidence=$("lconsentEvidence").value.trim();
 if(!name){alert("Enter a name.");return}
 if(requestedConsent==='Yes'&&!evidence){alert('Record consent evidence before marking an enquiry opted in.');return}
 let id=Date.now(),source=$("lsource").value,cleanPhone=phone.replace(/\D/g,''),contactId=null,canPromote=requestedConsent==='Yes';
 let cs=get('businessContacts');
 if(cleanPhone.length>=10){
   let old=cs.find(x=>x.phone===cleanPhone);
   if(old){contactId=old.id; if(old.optedOut){canPromote=false;} else if(canPromote && old.consent!=='Yes'){old.consent='Yes';old.consentEvidence=evidence;old.updatedAt=new Date().toISOString();set('businessContacts',cs);recordConsentEvent(old.id,'Opt-in',evidence);} }
   else {contactId=id+1;cs.unshift({id:contactId,name,phone:cleanPhone,language:'Odia',type:'Enquiry',consent:canPromote?'Yes':'No',consentEvidence:canPromote?evidence:'',notes:'Source: '+source,optedOut:false,updatedAt:new Date().toISOString()});set('businessContacts',cs);if(canPromote)recordConsentEvent(contactId,'Opt-in',evidence);}
 }
 let actualConsent=canPromote?'Yes':'No';
 let leads=get('leads');leads.unshift({id,name,contact:phone,source,status:$("lstatus").value,consent:actualConsent,consentEvidence:actualConsent==='Yes'?evidence:'',note:$("lnote").value,date:new Date().toLocaleDateString(),businessContactId:contactId});set('leads',leads);
 // Create an internal task for every enquiry. It is a service response to an initiated enquiry, not permission for marketing.
 let tasks=get('followups');tasks.unshift({id:id+2,contactId,contactName:name,date:new Date().toISOString().slice(0,10),purpose:'New enquiry response',note:actualConsent==='Yes'?'Reply to the information requested. Promotional follow-up is allowed only within the recorded consent.':'Reply only to the enquiry they initiated. No promotional follow-up without explicit opt-in.',status:'Pending',requiresConsent:actualConsent!=='Yes',createdAt:new Date().toISOString()});set('followups',tasks);
 ["lname","lcontact","lnote","lconsentEvidence"].forEach(x=>$(x).value="");$("lconsent").value='No';renderLeads();renderBusinessDesk();alert('Enquiry saved. An internal response task has been added to the follow-up queue.');
}
function renderLeads(){let a=get("leads");$("leadList").innerHTML=a.length?a.map(x=>`<div class="item"><b>${esc(x.name)}</b> <span class="pill">${esc(x.status)}</span><div class="muted">${esc(x.date)} · ${esc(x.source)} · Follow-up consent: ${esc(x.consent)}</div><div class="small">${esc(x.contact)} ${esc(x.note)}</div><label>Update status</label><select onchange="updateLead(${x.id},this.value)">${["New","Contacted","Interested","Consultation scheduled","Customer","Not proceeding"].map(s=>`<option ${s===x.status?"selected":""}>${s}</option>`).join("")}</select><div class="actions">${x.consent==='Yes'?`<button class="btn secondary small" onclick="draftLeadWhatsApp(${x.id})">Draft WhatsApp follow-up</button>`:`<span class="muted small">Follow-up disabled: no consent recorded.</span>`}<button class="btn danger small" onclick="delLead(${x.id})">Delete</button></div></div>`).join(""):"<p class='muted'>No enquiries recorded.</p>"}
function updateLead(id,status){let a=get("leads");a=a.map(x=>x.id===id?{...x,status}:x);set("leads",a);renderLeads()}
function delLead(id){set("leads",get("leads").filter(x=>x.id!==id));renderLeads()}
function clearLeads(){if(confirm("Permanently delete all locally stored leads?")){set("leads",[]);renderLeads()}}
function exportLeads(){let a=get("leads");if(!a.length){alert("No leads to export.");return}let cols=["date","name","contact","source","status","consent","note"];let csv=[cols.join(","),...a.map(x=>cols.map(k=>'"'+String(x[k]??"").replace(/"/g,'""')+'"').join(","))].join("\n");let blob=new Blob([csv],{type:"text/csv"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="sai-health-hub-leads.csv";link.click();URL.revokeObjectURL(url)}
function saveMetric(){let a=get("metrics");a.unshift({date:$("mdate").value,posts:$("mposts").value,reach:$("mreach").value,visits:$("mvisits").value,enq:$("menq").value,qualified:$("mqualified").value,customers:$("mcustomers").value,repeat:$("mrepeat").value});set("metrics",a);renderMetrics()}
function renderMetrics(){let a=get("metrics");$("metricList").innerHTML=a.length?a.map(x=>`<div class="item"><b>${esc(x.date||"Week not dated")}</b><div class="muted">Posts ${esc(x.posts)} · Reach ${esc(x.reach)} · Visits ${esc(x.visits)} · Enquiries ${esc(x.enq)} · Qualified ${esc(x.qualified)} · Customers ${esc(x.customers)} · Repeat/referral ${esc(x.repeat)}</div></div>`).join(""):"<p class='muted'>No weekly figures saved yet.</p>"}
