const creativeTopics={
 habits:{en:['One small habit to start today','Pick one realistic habit—take a short walk, add a fruit or vegetable, or set a regular bedtime. Consistency matters more than perfection.','Choose one habit and try it today.'],or:['ଆଜିଠାରୁ ଗୋଟିଏ ଛୋଟ ଅଭ୍ୟାସ','ଗୋଟିଏ ସହଜ ଅଭ୍ୟାସ ବାଛନ୍ତୁ—କିଛି ସମୟ ଚାଲନ୍ତୁ, ଫଳ କିମ୍ବା ପନିପରିବା ଖାଆନ୍ତୁ, କିମ୍ବା ନିୟମିତ ଶୋଇବା ସମୟ ରଖନ୍ତୁ।','ଆଜି ଗୋଟିଏ ଅଭ୍ୟାସ ଆରମ୍ଭ କରନ୍ତୁ।']},
 hydration:{en:['Make water part of your day','Keep water within reach and drink regularly. Your needs can vary with activity, weather and health conditions.','Build a simple hydration routine.'],or:['ଦିନଚର୍ଯ୍ୟାରେ ପାଣିକୁ ଗୁରୁତ୍ୱ ଦିଅନ୍ତୁ','ପାଖରେ ପାଣି ରଖନ୍ତୁ ଏବଂ ନିୟମିତ ପିଅନ୍ତୁ। ଆବଶ୍ୟକତା କାର୍ଯ୍ୟକଳାପ, ପାଣିପାଗ ଓ ସ୍ୱାସ୍ଥ୍ୟ ଅନୁସାରେ ବଦଳିପାରେ।','ସହଜ ପାଣି ପିଇବା ଅଭ୍ୟାସ ଗଢ଼ନ୍ତୁ।']},
 breakfast:{en:['Build a balanced breakfast','Try combining a source of protein, fibre-rich foods and a fruit or vegetable that suits your needs and preferences.','Plan a breakfast that works for you.'],or:['ସନ୍ତୁଳିତ ଜଳଖିଆ ପ୍ରସ୍ତୁତ କରନ୍ତୁ','ଆପଣଙ୍କ ଆବଶ୍ୟକତା ଅନୁସାରେ ପ୍ରୋଟିନ୍ ଉତ୍ସ, ଫାଇବର୍ ଥିବା ଖାଦ୍ୟ ଓ ଫଳ କିମ୍ବା ପନିପରିବା ମିଶାନ୍ତୁ।','ଆପଣଙ୍କ ପାଇଁ ଉପଯୁକ୍ତ ଜଳଖିଆ ଯୋଜନା କରନ୍ତୁ।']},
 movement:{en:['Add movement to your routine','A short walk, gentle stretching or everyday activity can be a practical starting point. Choose an option appropriate for your ability.','Find a movement that feels manageable.'],or:['ଦୈନନ୍ଦିନ ଜୀବନରେ ଶାରୀରିକ ଗତିବିଧି ଯୋଡ଼ନ୍ତୁ','ଅଳ୍ପ ଚାଲିବା, ହାଲୁକା ଷ୍ଟ୍ରେଚିଂ କିମ୍ବା ଦୈନନ୍ଦିନ କାମ ଏକ ଭଲ ଆରମ୍ଭ ହୋଇପାରେ। ନିଜ ସାମର୍ଥ୍ୟ ଅନୁସାରେ ବାଛନ୍ତୁ।','ସହଜ ଲାଗୁଥିବା ଗତିବିଧି ବାଛନ୍ତୁ।']},
 sleep:{en:['Create a calmer bedtime routine','Try a regular sleep schedule and a relaxing wind-down routine. Reduce bright screens close to bedtime if practical.','Make room for a restful routine.'],or:['ଶୋଇବା ପୂର୍ବରୁ ଶାନ୍ତ ଅଭ୍ୟାସ ଗଢ଼ନ୍ତୁ','ନିୟମିତ ଶୋଇବା ସମୟ ଓ ଆରାମଦାୟକ ରାତିର ଅଭ୍ୟାସ ରଖନ୍ତୁ। ସମ୍ଭବ ହେଲେ ଶୋଇବା ପୂର୍ବରୁ ଉଜ୍ଜ୍ୱଳ ସ୍କ୍ରିନ୍ କମାନ୍ତୁ।','ଭଲ ବିଶ୍ରାମ ପାଇଁ ସମୟ ରଖନ୍ତୁ।']},
 coach:{en:['Meet your health coach','At Sai Health Hub, we focus on practical everyday habits, supportive conversations and goals that are realistic for each person.','Message us to learn about our coaching sessions.'],or:['ଆପଣଙ୍କ ହେଲ୍ଥ କୋଚ୍‌ଙ୍କ ସହ ପରିଚିତ ହୁଅନ୍ତୁ','Sai Health Hub ରେ ଆମେ ଦୈନନ୍ଦିନ ଅଭ୍ୟାସ, ସହଯୋଗମୂଳକ ଆଲୋଚନା ଓ ବାସ୍ତବସମ୍ମତ ଲକ୍ଷ୍ୟକୁ ଗୁରୁତ୍ୱ ଦେଉଛୁ।','କୋଚିଂ ସେସନ୍ ବିଷୟରେ ଜାଣିବାକୁ ମେସେଜ୍ କରନ୍ତୁ।']},
 community:{en:['Healthy habits grow in community','Join a friendly conversation about everyday food choices, movement and routines. Participation is optional and welcoming.','Ask us about the next community session.'],or:['ସମୁଦାୟରେ ସୁସ୍ଥ ଅଭ୍ୟାସ ଗଢ଼ିଉଠେ','ଦୈନନ୍ଦିନ ଖାଦ୍ୟ, ଶାରୀରିକ ଗତିବିଧି ଓ ଅଭ୍ୟାସ ବିଷୟରେ ଏକ ସହଜ ଆଲୋଚନାରେ ଯୋଗଦିଅନ୍ତୁ। ଯୋଗଦେବା ଇଚ୍ଛାଧୀନ।','ପରବର୍ତ୍ତୀ ସେସନ୍ ବିଷୟରେ ପଚାରନ୍ତୁ।']}
};
function getCreativeCopy(){let item=creativeTopics[$('crTopic').value],lang=$('crLang').value;let idx=lang==='or'?1:0;let a=item[idx];if(lang==='mix')return item[0].map((x,i)=>x+'\n'+item[1][i]);return a}
function makePoster(){let c=$('posterCanvas'),ctx=c.getContext('2d'),lang=$('crLang').value,base=getCreativeCopy();let head=$('crHeadline').value.trim()||base[0],body=$('crBody').value.trim()||base[1],cta=$('crCta').value.trim()||base[2],footer=$('crFooter').value.trim();if(lang==='or'){let b=creativeTopics[$('crTopic').value][1];if(!$('crHeadline').value.trim())head=b[0];if(!$('crBody').value.trim())body=b[1];if(!$('crCta').value.trim())cta=b[2]}
ctx.fillStyle='#eaf5ee';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#145c3a';ctx.fillRect(0,0,1080,330);ctx.fillStyle='#d7f1df';ctx.beginPath();ctx.arc(950,90,220,0,Math.PI*2);ctx.fill();ctx.fillStyle='#145c3a';ctx.font='bold 34px sans-serif';ctx.fillText('SAI HEALTH HUB',76,90);ctx.fillStyle='#fff';ctx.font='bold 76px sans-serif';wrapCanvas(ctx,head,76,205,900,94);ctx.fillStyle='#183126';ctx.font='42px sans-serif';wrapCanvas(ctx,body,76,470,900,66);ctx.fillStyle='#218653';ctx.roundRect?ctx.roundRect(76,1000,928,170,32):ctx.fillRect(76,1000,928,170);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 42px sans-serif';wrapCanvas(ctx,cta,120,1070,840,58);ctx.fillStyle='#145c3a';ctx.font='bold 32px sans-serif';ctx.fillText(footer,76,1260);ctx.font='24px sans-serif';ctx.fillStyle='#66766d';ctx.fillText('Healthy Habits. Better Living..',76,1305);}
function wrapCanvas(ctx,text,x,y,maxW,lineH){let words=String(text).split(/\s+/),line='';for(let w of words){let test=line?line+' '+w:w;if(ctx.measureText(test).width>maxW&&line){ctx.fillText(line,x,y);line=w;y+=lineH}else line=test}if(line)ctx.fillText(line,x,y)}
function downloadPoster(){makePoster();let a=document.createElement('a');a.download='sai-health-hub-poster.png';a.href=$('posterCanvas').toDataURL('image/png');a.click()}
function makeReel(){let lang=$('crLang').value,t=$('crTopic').value,copy=getCreativeCopy();let en=creativeTopics[t][0],or=creativeTopics[t][1];let headline=$('crHeadline').value.trim()||(lang==='or'?or[0]:en[0]),body=$('crBody').value.trim()||(lang==='or'?or[1]:en[1]),cta=$('crCta').value.trim()||(lang==='or'?or[2]:en[2]);let od=lang==='or'||lang==='mix';lastReel=`SAI HEALTH HUB · REEL (20–30 seconds)\n\nHOOK (0–3 sec): ${headline}\n\nSCENE 1 (3–9 sec): Coach on camera. Say: ${body}\n\nSCENE 2 (9–18 sec): Show a simple everyday example or demonstration. Add on-screen text: One small step at a time.\n\nSCENE 3 (18–24 sec): Coach summarises the practical tip. Keep it realistic; do not promise a health outcome.\n\nCALL TO ACTION (24–30 sec): ${cta}\n\nCAPTION: ${body}\n\nHASHTAGS: #SaiHealthHub #HealthyHabits #Khordha #DailyHealthHabits\n\nPRODUCTION: Vertical 9:16, clear natural light, captions on screen, use original or properly licensed music. Obtain consent from anyone featured.`;if(od)lastReel+='\n\nଓଡ଼ିଆ ଭାର୍ସନ୍:\n'+or[0]+'\n'+or[1]+'\n'+or[2];$('reelOutput').textContent=lastReel}
function copyReel(){if(!lastReel)makeReel();copyText(lastReel)}
function copyCreativeCaption(){let c=$('crBody').value+'\n\n'+$('crCta').value+'\n\n#SaiHealthHub #HealthyHabits #Khordha';copyText(c)}
function saveCreative(){let a=get('creative');a.unshift({id:Date.now(),topic:$('crTopic').value,lang:$('crLang').value,headline:$('crHeadline').value,body:$('crBody').value,cta:$('crCta').value,reel:lastReel,createdAt:new Date().toISOString()});set('creative',a);alert('Creative brief and Reel draft saved in this browser. Include creative in your next JSON backup.')}
