const stageOrder=['Day 1','Day 7','Day 14','Day 21','Day 30','Day 90'];

function setStagePrompts(){let s=$('checkStage').value,p={ 'Day 1':['Baseline','Capture starting routines, personal goals, preferences and expectations.'], 'Day 7':['Pilot review','Review experience, habits attempted, practical difficulties and satisfaction.'], 'Day 14':['Two-week review','Explore consistency, barriers and any changing preferences.'], 'Day 21':['Three-week review','Review which habits felt manageable, confidence and remaining challenges.'], 'Day 30':['Monthly review','Record the customer’s own view of progress, useful changes and next priorities.'], 'Day 90':['Quarterly review','Review long-term consistency, feedback and customer-defined future goals.'] }[s];$('stagePrompt').textContent=p[0]+': '+p[1];$('checkWins').placeholder=p[0]+': what felt useful or worked well?';$('checkChallenges').placeholder=p[0]+': what was difficult or changed?';$('checkNext').placeholder='Customer’s preferred next step after '+p[0].toLowerCase();}

function saveCustomer(){let name=$('tcName').value.trim();if(!name){alert('Enter a customer code or display name.');return}if(!$('tcConsent').checked){alert('Please confirm the customer agreed to this record being stored.');return}let a=get('customers'),item={id:a.find(x=>x.name.toLowerCase()===name.toLowerCase())?.id||Date.now(),name,language:$('tcLang').value,goal:$('tcGoal').value,activity:$('tcActivity').value,content:$('tcContent').value,barrier:$('tcBarrier').value,coaching:$('tcCoach').value,consent:true,updatedAt:new Date().toISOString()};a=a.filter(x=>x.id!==item.id);a.unshift(item);set('customers',a);renderCustomerOptions();$('tcName').value='';$('tcBarrier').value='';alert('Customer profile saved on this device.')}
function renderCustomerOptions(){let a=get('customers'),opts=a.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');['checkCustomer','viewCustomer','mediaCustomer'].forEach(id=>{let el=$(id);if(el){let old=el.value;el.innerHTML=opts||'<option value="">No customers yet</option>';if(a.some(x=>String(x.id)===old))el.value=old}});renderMediaList()}
function saveCheckin(){let id=Number($('checkCustomer').value),c=get('customers').find(x=>x.id===id);if(!c){alert('Save a customer profile first.');return}let date=$('checkDate').value||new Date().toISOString().slice(0,10),n=v=>v===''?null:Number(v),v={id:Date.now(),customerId:id,stage:$('checkStage').value,date,habit:n($('checkHabit').value),engage:n($('checkEngage').value),satisfy:n($('checkSatisfy').value),confidence:n($('checkConfidence').value),wins:$('checkWins').value, challenges:$('checkChallenges').value,next:$('checkNext').value};if([v.habit,v.engage,v.satisfy,v.confidence].every(x=>x===null)&&![v.wins,v.challenges,v.next].some(x=>x.trim())){alert('Enter at least one actual score or feedback item.');return}let a=get('checkins');a.unshift(v);set('checkins',a);['checkHabit','checkEngage','checkSatisfy','checkConfidence','checkWins','checkChallenges','checkNext'].forEach(k=>$(k).value='');renderCustomerProgress();alert('Stage check-in saved. Missing values remain blank, not zero.')}
function renderCustomerProgress(){let id=Number($('viewCustomer')?.value||$('checkCustomer')?.value),a=get('checkins').filter(x=>x.customerId===id).sort((x,y)=>new Date(x.date)-new Date(y.date)),metric=$('chartMetric')?.value||'habit',labels={habit:'Habit completion',engage:'Engagement',satisfy:'Satisfaction',confidence:'Confidence'},vals=a.filter(x=>x[metric]!==null&&x[metric]!==undefined);$('customerTimeline').innerHTML=a.length?a.map(x=>`<div class="item"><b>${esc(x.stage)} · ${esc(x.date)}</b><div class="muted">Habit: ${x.habit===null?'—':x.habit+'%'} · Engagement: ${x.engage??'—'}/10 · Satisfaction: ${x.satisfy??'—'}/10 · Confidence: ${x.confidence??'—'}/10</div><div>Worked: ${esc(x.wins||'Not recorded')}</div><div>Challenge: ${esc(x.challenges||'Not recorded')}</div><div>Next: ${esc(x.next||'Not recorded')}</div></div>`).join(''):'No stage check-ins recorded yet.';let c=$('progressChart'),ctx=c?.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#66766d';ctx.font='22px sans-serif';ctx.fillText(labels[metric]+' · recorded values only',22,32);ctx.strokeStyle='#dce8df';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(70,65);ctx.lineTo(70,300);ctx.lineTo(860,300);ctx.stroke();let max=metric==='habit'?100:10;for(let t=0;t<=4;t++){let y=300-t*55;ctx.fillText(String(max*t/4),25,y+6);ctx.strokeStyle='#edf2ee';ctx.beginPath();ctx.moveTo(70,y);ctx.lineTo(860,y);ctx.stroke()}let pts=vals.map(x=>({x:100+(a.indexOf(x))*Math.max(1,740/Math.max(1,a.length-1)),y:300-(x[metric]/max)*220,label:x.stage}));ctx.strokeStyle='#218653';ctx.lineWidth=5;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();pts.forEach(p=>{ctx.fillStyle='#145c3a';ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#183126';ctx.font='18px sans-serif';ctx.fillText(p.label,p.x-28,330)});$('comparisonText').textContent=vals.length>1?`${labels[metric]}: ${vals[0][metric]} → ${vals[vals.length-1][metric]} (${vals[vals.length-1][metric]-vals[0][metric]>0?'+':''}${vals[vals.length-1][metric]-vals[0][metric]}). Based only on recorded check-ins; this is not proof of causation.`:'Need at least two recorded values for this measure to compare stages.'}
let currentMediaUrl='';function previewCustomerMedia(e){let f=e.target.files[0];if(!f)return;if(currentMediaUrl)URL.revokeObjectURL(currentMediaUrl);currentMediaUrl=URL.createObjectURL(f);let el=$('mediaPreview');el.innerHTML=f.type.startsWith('video/')?`<video controls playsinline style="width:100%;max-height:280px" src="${currentMediaUrl}"></video><p>${esc(f.name)} · ${Math.round(f.size/1024/1024*10)/10} MB · Local preview only</p>`:`<img alt="Selected original photo preview" src="${currentMediaUrl}" style="max-width:100%;max-height:280px;border-radius:10px"><p>${esc(f.name)} · Local preview only</p>`}
function saveMediaRecord(){let f=$('customerMedia').files[0],id=Number($('mediaCustomer').value);if(!f||!id){alert('Select a customer and media file.');return}if(!$('mediaConsent').checked){alert('Explicit media consent is required.');return}let a=get('mediaRefs');a.unshift({id:Date.now(),customerId:id,fileName:f.name,mime:f.type,size:f.size,purpose:$('mediaPurpose').value,consent:true,date:new Date().toISOString()});set('mediaRefs',a);renderMediaList();$('mediaPurpose').value='';alert('Media reference saved. The original file remains on this device; it is not embedded in the backup.')}
function renderMediaList(){let a=get('mediaRefs');if($('mediaList'))$('mediaList').innerHTML=a.length?a.map(x=>`<div class="item">${esc(get('customers').find(c=>c.id===x.customerId)?.name||'Customer')} · ${esc(x.fileName)} · ${esc(x.purpose)} · consent recorded</div>`).join(''):'No media references saved.'}
async function runCustomerAI(){let id=Number($('viewCustomer').value||$('checkCustomer').value),c=get('customers').find(x=>x.id===id),checks=get('checkins').filter(x=>x.customerId===id).sort((a,b)=>new Date(a.date)-new Date(b.date));if(!c){$('customerAiStatus').textContent='Save/select a customer profile first.';return}let mode=$('customerAiMode').value,payload={kind:'customer_'+mode.toLowerCase().replaceAll(' ','_'),language:c.language,brief:$('customerAiBrief').value,customer_profile:{goal:c.goal,preferred_activity:c.activity,content_preference:c.content,practical_barrier:c.barrier,coaching_preference:c.coaching},recorded_checkins:checks,requirements:'Compare only recorded values. Identify missing data explicitly. Do not diagnose, infer medical conditions, invent outcomes, promise weight loss, or recommend restrictive diets. Suggest a practical customer-led next plan with stage milestones and coach review. Keep identifiable information out of generated public content.'};$('customerAiStatus').textContent='Connecting to secure AI backend…';try{let r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok)throw Error(j.error||'AI backend unavailable');$('customerAiResult').textContent=j.text||JSON.stringify(j,null,2);$('customerAiResult').style.display='block';$('customerAiStatus').textContent='AI draft received. Review accuracy, privacy and compliance before use.'}catch(e){$('customerAiStatus').textContent='AI not connected: '+e.message+' The server-side AI service could not be reached. Try again in a moment.'}}
