let idPreviewUrls=[];
function previewIdImage(ev){let files=[...(ev.target.files||[])];idPreviewUrls.forEach(u=>URL.revokeObjectURL(u));idPreviewUrls=[];let box=$('idPreview');box.innerHTML='';if(!files.length){box.textContent='No document image selected.';return}files.forEach(f=>{if(!f.type.startsWith('image/'))return;let u=URL.createObjectURL(f);idPreviewUrls.push(u);let img=document.createElement('img');img.src=u;img.alt='Temporary document preview';img.style='max-width:100%;max-height:180px;margin:5px;border-radius:8px';box.appendChild(img)});let note=document.createElement('p');note.className='muted small';note.textContent=files.length+' image(s) selected · temporary preview only';box.appendChild(note)}
function clearIdPreview(){idPreviewUrls.forEach(u=>URL.revokeObjectURL(u));idPreviewUrls=[];if($('idCamera'))$('idCamera').value='';if($('idGallery'))$('idGallery').value='';if($('idPreview'))$('idPreview').textContent='Temporary image preview cleared.'}
function idCounts(ref){let docs=get('idDocs').filter(d=>!ref||d.customerRef===ref),primary=new Set(['Aadhaar','Voter ID','Driving Licence','Passport','PAN Card']),p=new Set(),sec=new Set();docs.forEach(d=>(primary.has(d.category)?p:sec).add(d.category));return {p:p.size,s:sec.size,ok:p.size>=2||(p.size>=1&&sec.size>=1)}}
function renderIdDocs(){let docs=get('idDocs'),ref=$('idCustomerRef')?.value.trim(),c=idCounts(ref);$('idRuleSummary').innerHTML='<b>Distinct primary types for '+esc(ref||'all customers')+':</b> '+c.p+' · <b>Distinct secondary types:</b> '+c.s+'<br><b>Rule result:</b> '+(c.ok?'<span class="pill">Eligible for owner review</span>':'<span class="pill" style="background:#fff4dc;color:#8a5a00">Pending / exception review</span>');$('idDocumentList').innerHTML=docs.length?docs.map(d=>'<div class="item"><b>'+esc(d.customerRef)+'</b> · '+esc(d.category)+' · '+esc(d.side)+'<div class="muted">Consent recorded: '+esc(d.consentAt)+'</div></div>').join(''):'No document categories recorded.';renderOwnerIdHistory()}
function addIdDocument(){let ref=$('idCustomerRef').value.trim(),category=$('idCategory').value,side=$('idSide').value;if(!ref){alert('Enter a customer reference.');return}if(!$('idConsent').checked){alert('Customer purpose notice and consent are required.');return}let docs=get('idDocs');if(docs.some(d=>d.customerRef===ref&&d.category===category)){if(!confirm('This document type is already recorded for this customer. Add another side/copy? It will not count as a new distinct type.'))return}docs.unshift({id:Date.now(),customerRef:ref,category,side,consentAt:new Date().toISOString()});set('idDocs',docs);$('idConsent').checked=false;clearIdPreview();renderIdDocs();alert('Document type recorded. Image files were not saved.');}
function saveOwnerIdReview(){let ref=$('ownerIdRef').value.trim(),initials=$('ownerIdInitials').value.trim(),decision=$('ownerIdDecision').value,just=$('ownerIdJustification').value.trim(),verify=$('ownerIdVerification').value.trim();if(!ref||!initials){alert('Customer reference and owner initials are required.');return}if(decision==='Approve exception'&&(!just||!verify)){alert('Exception approval requires detailed justification and additional verification notes.');return}let d=get('idDocs').filter(x=>x.customerRef===ref),primary=new Set(['Aadhaar','Voter ID','Driving Licence','Passport','PAN Card']),p=new Set(),sec=new Set();d.forEach(x=>(primary.has(x.category)?p:sec).add(x.category));let valid=p.size>=2||(p.size>=1&&sec.size>=1);if(!valid&&decision==='Keep pending'){}let a=get('idReviews');a.unshift({id:Date.now(),customerRef:ref,status:$('ownerIdStatus').value,source:$('ownerIdSource').value.trim(),reference:$('ownerIdTxn').value.trim(),feedback:$('ownerIdFeedback').value.trim(),owner:initials,decision,justification:just,verification:verify,rule:{primary:p.size,secondary:sec.size,standardEligible:valid},timestamp:new Date().toISOString()});set('idReviews',a);renderOwnerIdHistory();alert('Owner review saved locally. No government database was queried.');}
function renderOwnerIdHistory(){let a=get('idReviews');if($('ownerIdHistory'))$('ownerIdHistory').innerHTML=a.length?a.map(x=>'<div class="item"><b>'+esc(x.customerRef)+' · '+esc(x.status)+'</b><div>'+esc(x.decision)+' · '+esc(x.owner)+' · '+esc(new Date(x.timestamp).toLocaleString())+'</div><div class="muted">Source: '+esc(x.source||'Not recorded')+' · Rule: '+x.rule.primary+' primary / '+x.rule.secondary+' secondary · '+(x.rule.standardEligible?'standard combination':'rule not met')+'</div><p>'+esc(x.feedback||'No feedback')+'</p>'+(x.justification?'<p><b>Exception justification:</b> '+esc(x.justification)+'</p>':'')+'</div>').join(''):'No owner review entries recorded.'}
function saveMasterIdProfile(){let ref=$('masterIdRef').value.trim(),name=$('masterName').value.trim();if(!ref||!name){alert('Customer reference and owner-reviewed name are required.');return}let a=get('masterProfiles');a=a.filter(x=>x.customerRef!==ref);a.unshift({customerRef:ref,name,mobile:$('masterMobile').value.trim(),variations:$('masterVariations').value.trim(),updatedAt:new Date().toISOString()});set('masterProfiles',a);$('masterIdStatus').textContent='Editable profile draft saved locally. No identity approval is implied.'}


// Business Desk: local contact CRM, consent evidence, due follow-ups and bookings.
function recordConsentEvent(contactId,action,evidence){let a=get('consentEvents');a.unshift({id:Date.now()+Math.random(),contactId,action,evidence:evidence||'',timestamp:new Date().toISOString()});set('consentEvents',a)}
function saveBusinessContact(){let name=$('bdName').value.trim(),phone=$('bdPhone').value.replace(/\D/g,'');if(!name||phone.length<10){alert('Enter a name and a valid phone number.');return}let consent=$('bdConsent').value;if(consent==='Yes'&&!$('bdConsentEvidence').value.trim()){alert('Record where/how explicit opt-in was received.');return}let a=get('businessContacts'),old=a.find(x=>x.phone===phone),x={id:old?.id||Date.now(),name,phone,language:$('bdLang').value,type:$('bdType').value,consent,consentEvidence:$('bdConsentEvidence').value.trim(),notes:$('bdNotes').value.trim(),optedOut:old?.optedOut||false,updatedAt:new Date().toISOString()};a=a.filter(y=>y.id!==x.id);a.unshift(x);set('businessContacts',a);if(consent==='Yes'&&!old?.consent)recordConsentEvent(x.id,'Opt-in',x.consentEvidence);else if(consent==='Yes'&&old?.consentEvidence!==x.consentEvidence)recordConsentEvent(x.id,'Opt-in evidence updated',x.consentEvidence);$('bdName').value=$('bdPhone').value=$('bdConsentEvidence').value=$('bdNotes').value='';renderBusinessDesk();alert('Contact saved on this device.');}
function renderBusinessDesk(){let a=get('businessContacts'),opts=a.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.phone)}</option>`).join('');['fuContact','bookContact'].forEach(id=>{let el=$(id);if(el){let old=el.value;el.innerHTML=opts||'<option value="">No contacts yet</option>';if(a.some(x=>String(x.id)===old))el.value=old}});let c=$('businessContactList');if(c)c.innerHTML=a.length?a.map(x=>`<div class="item"><b>${esc(x.name)}</b> · ${esc(x.phone)} <span class="pill">${esc(x.type)}</span><div class="muted">${esc(x.language)} · Follow-up consent: ${x.consent==='Yes'&&!x.optedOut?'Yes':'No'}${x.consentEvidence?' · Evidence: '+esc(x.consentEvidence):''}</div><div>${esc(x.notes||'No notes')}</div><div class="actions"><button class="btn secondary" onclick="convertContactToCustomer(${x.id})">Mark customer</button><button class="btn secondary" onclick="draftContactWhatsApp(${x.id})">Draft WhatsApp</button><button class="btn secondary" onclick="recordOptOut(${x.id})">Record STOP</button><button class="btn danger" onclick="deleteBusinessContact(${x.id})">Delete</button></div></div>`).join(''):'No contacts saved yet.';let ce=get('consentEvents');if($('consentEventList'))$('consentEventList').innerHTML=ce.length?ce.slice(0,100).map(e=>`<div class="item"><b>${esc(a.find(c=>c.id===e.contactId)?.name||'Contact')}</b> · ${esc(e.action)}<div class="muted">${esc(e.evidence)} · ${esc(new Date(e.timestamp).toLocaleString())}</div></div>`).join(''):'No consent events recorded.';let f=get('followups').sort((x,y)=>x.date.localeCompare(y.date));if($('followupList'))$('followupList').innerHTML=f.length?f.map(x=>{let z=a.find(c=>c.id===x.contactId);return `<div class="item"><b>${esc(z?.name||x.contactName||'Enquiry')} · ${esc(x.date)}</b> <span class="pill">${esc(x.status)}</span><div>${esc(x.purpose)} · ${esc(x.note||'')}</div><div class="actions"><button class="btn secondary" onclick="completeFollowup(${x.id})">Mark complete</button>${z&&z.consent==='Yes'&&!z.optedOut&&!x.requiresConsent?`<button class="btn secondary" onclick="draftContactWhatsApp(${z.id})">Prepare message</button>`:''}</div></div>`}).join(''):'No follow-ups scheduled.';let b=get('consultations').sort((x,y)=>(x.date+x.time).localeCompare(y.date+y.time));if($('consultationList'))$('consultationList').innerHTML=b.length?b.map(x=>`<div class="item"><b>${esc(a.find(c=>c.id===x.contactId)?.name||'Deleted contact')} · ${esc(x.date)} ${esc(x.time)}</b><div>${esc(x.mode)} · ${esc(x.duration)} · ${esc(x.agenda)}</div><div class="actions"><button class="btn secondary" onclick="bookingWhatsApp(${x.id})">Prepare reminder</button><button class="btn secondary" onclick="completeBooking(${x.id})">Mark completed</button></div></div>`).join(''):'No consultations booked.';}
function saveFollowup(){let id=Number($('fuContact').value),c=get('businessContacts').find(x=>x.id===id),date=$('fuDate').value;if(!c||!date){alert('Select a contact and follow-up date.');return}if(c.optedOut||c.consent!=='Yes'){alert('Follow-up cannot be scheduled for a promotional contact without current explicit consent. Record service replies only within the original enquiry.');return}let a=get('followups');a.unshift({id:Date.now(),contactId:id,date,purpose:$('fuPurpose').value,note:$('fuNote').value.trim(),status:'Pending',createdAt:new Date().toISOString()});set('followups',a);$('fuNote').value='';renderBusinessDesk();}
function completeFollowup(id){let a=get('followups');a=a.map(x=>x.id===id?{...x,status:'Completed',completedAt:new Date().toISOString()}:x);set('followups',a);renderBusinessDesk()}
function saveConsultation(){let id=Number($('bookContact').value),c=get('businessContacts').find(x=>x.id===id),date=$('bookDate').value,time=$('bookTime').value;if(!c||!date||!time){alert('Select a contact, date and time.');return}let a=get('consultations');a.unshift({id:Date.now(),contactId:id,date,time,mode:$('bookMode').value,duration:$('bookDuration').value,agenda:$('bookAgenda').value.trim(),status:'Booked',createdAt:new Date().toISOString()});set('consultations',a);$('bookAgenda').value='';renderBusinessDesk();alert('Consultation saved locally. Send confirmation manually.');}
function completeBooking(id){let a=get('consultations').map(x=>x.id===id?{...x,status:'Completed'}:x);set('consultations',a);renderBusinessDesk()}
function draftContactWhatsApp(id){let c=get('businessContacts').find(x=>x.id===id);if(!c)return;if(c.optedOut){alert('This contact opted out.');return}if(c.consent!=='Yes'){alert('No promotional follow-up consent is recorded. You may only respond to a current enquiry within its scope.');return}document.querySelector('[data-tab="whatsapp"]').click();$('waName').value=c.name.split(' ')[0];$('waLang').value=c.language==='Odia'?'or':'en';$('waType').value='follow';makeWaDraft();$('waConsent').checked=true;}
function recordOptOut(id){recordConsentEvent(id,'Opt-out / STOP','Opt-out recorded by owner');let a=get('businessContacts').map(x=>x.id===id?{...x,consent:'No',optedOut:true,optedOutAt:new Date().toISOString()}:x);set('businessContacts',a);renderBusinessDesk();alert('Opt-out recorded. Do not send further promotional messages.');}
function deleteBusinessContact(id){if(!confirm('Delete this contact? Related follow-up and booking history will remain without the contact name.'))return;set('businessContacts',get('businessContacts').filter(x=>x.id!==id));renderBusinessDesk()}
function convertContactToCustomer(id){let c=get('businessContacts').find(x=>x.id===id);if(!c)return;let leads=get('leads'),l=leads.find(x=>String(x.contact||'').replace(/\D/g,'')===c.phone);if(l){l.status='Customer';set('leads',leads)}let cust=get('customers');if(!cust.some(x=>x.name.toLowerCase()===c.name.toLowerCase())){cust.unshift({id:Date.now(),name:c.name,language:c.language,goal:'Build consistent daily habits',activity:'Not specified',content:'Not specified',barrier:'',coaching:'To be discussed',consent:false,updatedAt:new Date().toISOString()});set('customers',cust)}set('businessContacts',get('businessContacts').map(x=>x.id===id?{...x,type:'Customer'}:x));renderBusinessDesk();renderCustomerOptions();alert('Moved into the customer workflow. Obtain separate customer-record consent before adding coaching details.');}
function bookingWhatsApp(id){let x=get('consultations').find(y=>y.id===id),c=get('businessContacts').find(y=>y.id===x?.contactId);if(!x||!c)return;let msg=`Hello ${c.name}, this is Sai Health Hub. Your consultation is scheduled for ${x.date} at ${x.time} (${x.mode}, ${x.duration}). Please reply if you need to reschedule.`;copyText(msg);}
function exportContactsVCF(){let a=get('businessContacts');if(!a.length){alert('No contacts to export.');return}let v=a.map(x=>`BEGIN:VCARD\nVERSION:3.0\nFN:${x.name.replace(/[\n;]/g,' ')}\nTEL;TYPE=CELL:${x.phone}\nNOTE:Sai Health Hub contact. Consent:${x.consent==='Yes'&&!x.optedOut?'Opt-in':'No promotional opt-in'}\nEND:VCARD`).join('\n');downloadBlob(v,'sai-health-hub-contacts.vcf','text/vcard')}
function exportBusinessCSV(){let a=get('businessContacts');let rows=[['Name','Phone','Language','Type','Consent','Consent evidence','Notes'],...a.map(x=>[x.name,x.phone,x.language,x.type,x.consent==='Yes'&&!x.optedOut?'Yes':'No',x.consentEvidence,x.notes])];downloadBlob(rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'sai-health-hub-crm.csv','text/csv')}
function downloadBlob(text,name,type){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1200)}
function makeLeadQR(){let msg=$('qrPrompt').value.trim();if(!msg){alert('Enter a WhatsApp enquiry prompt.');return}let url='https://wa.me/917064160064?text='+encodeURIComponent(msg);$('qrLink').textContent=url;$('leadQr').innerHTML='';if(typeof QRCode==='undefined'){$('leadQr').textContent='QR library is unavailable. Open the app online and retry.';return}new QRCode($('leadQr'),{text:url,width:210,height:210,colorDark:'#145c3a',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}
function downloadLeadQR(){let c=$('leadQr').querySelector('canvas');if(c){let a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='sai-health-hub-whatsapp-enquiry-qr.png';a.click();return}let i=$('leadQr').querySelector('img');if(i){let a=document.createElement('a');a.href=i.src;a.download='sai-health-hub-whatsapp-enquiry-qr.png';a.click();return}alert('Generate the QR code first.');}
async function bytesToBase64(bytes){let bin='';for(let i=0;i<bytes.length;i+=32768)bin+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(bin)}
async function exportEncryptedBackup(){let pass=$('encPassword').value;if(pass.length<10){alert('Use a backup password of at least 10 characters.');return}if(!crypto?.subtle){alert('Secure browser cryptography is unavailable. Open through HTTPS or a supported local browser.');return}let keys=['plan','content','leads','metrics','creative','customers','checkins','mediaRefs','idDocs','idReviews','masterProfiles','businessContacts','followups','consultations'];let payload={app:'Sai Health Hub',version:3,exportedAt:new Date().toISOString(),data:Object.fromEntries(keys.map(k=>[k,get(k)])),language:localStorage.getItem('shh_language')||'en'};let salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),enc=new TextEncoder(),material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']),key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);let cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(JSON.stringify(payload)));let bytes=new Uint8Array([...salt,...iv,...new Uint8Array(cipher)]);downloadBlob(JSON.stringify({format:'SHH-AES-GCM-1',payload:bytesToBase64(bytes)},null,2),'sai-health-hub-encrypted-backup.shhenc','application/json');$('encBackupStatus').textContent='Encrypted backup created. Store the password separately and keep the file private.';}
async function restoreEncryptedBackup(ev){let f=ev.target.files?.[0],pass=$('encPassword').value;if(!f)return;if(pass.length<10){alert('Enter the backup password first (10+ characters).');ev.target.value='';return}try{let obj=JSON.parse(await f.text());if(obj.format!=='SHH-AES-GCM-1')throw Error('Unsupported encrypted backup');let bytes=Uint8Array.from(atob(obj.payload),c=>c.charCodeAt(0)),salt=bytes.slice(0,16),iv=bytes.slice(16,28),cipher=bytes.slice(28),enc=new TextEncoder(),material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']),key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['decrypt']);let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher),data=JSON.parse(new TextDecoder().decode(plain));if(!data.data||!Array.isArray(data.data.leads))throw Error('Backup contents are invalid');if(!confirm('Restore encrypted backup? Current local records will be replaced.'))return;Object.entries(data.data).forEach(([k,v])=>{if(Array.isArray(v))set(k,v)});if(data.language)localStorage.setItem('shh_language',data.language);renderPlan();renderContent();renderLeads();renderMetrics();renderIdDocs();renderCustomerOptions();renderCustomerProgress();renderMediaList();renderBusinessDesk();renderQAChecks();makeWaDraft();setLanguage(localStorage.getItem('shh_language')||'en');$('encBackupStatus').textContent='Encrypted backup decrypted and restored locally.';}catch(e){alert('Restore failed: wrong password, damaged file or unsupported format. '+e.message)}finally{ev.target.value=''}}
async function runRecoverySelfTest(){try{if(!crypto?.subtle)throw Error('Web Crypto unavailable; use HTTPS.');let test='Sai Health Hub local recovery test',pass='Test-Only-Password-2026',salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),enc=new TextEncoder(),m=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']),k=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:10000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt','decrypt']),c=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,enc.encode(test)),d=await crypto.subtle.decrypt({name:'AES-GCM',iv},k,c);if(new TextDecoder().decode(d)!==test)throw Error('round-trip mismatch');$('recoveryStatus').textContent='PASS: browser encryption/decryption round-trip works. This is not a server backup or disaster-recovery test.';}catch(e){$('recoveryStatus').textContent='FAIL: '+e.message}}
async function checkHostingReadiness(){let el=$('hostingCheck');try{let r=await fetch('/api/ai/status',{headers:{Accept:'application/json'}});let j=await r.json();el.textContent=r.ok?'Backend responded. AI configured: '+!!j.configured+'. Confirm authentication/database endpoints separately.':'Backend health endpoint returned '+r.status+'.'}catch(e){el.textContent='No backend health endpoint detected at this URL. '+e.message}}

function renderQAChecks(){let a=get('qaChecks');document.querySelectorAll('[data-qa]').forEach(el=>el.checked=a.includes(el.dataset.qa));if($('qaStatus'))$('qaStatus').textContent=a.length+' of 16 acceptance checks marked passed. Untested items must remain unchecked.'}
function saveQAChecks(){let a=[...document.querySelectorAll('[data-qa]:checked')].map(el=>el.dataset.qa);set('qaChecks',a);renderQAChecks();}
$('checkDate').value=new Date().toISOString().slice(0,10);$('fuDate').value=new Date().toISOString().slice(0,10);$('bookDate').value=new Date().toISOString().slice(0,10);setStagePrompts();renderBusinessDesk();renderQAChecks();



let latestAIText='';
async function checkAIStatus(){const el=document.getElementById('aiStatus');el.textContent='Checking secure AI backend…';try{const r=await fetch('/api/ai/status',{headers:{'Accept':'application/json'}});const j=await r.json();if(!r.ok)throw new Error(j.error||'Backend unavailable');el.textContent=j.configured?'AI backend connected · '+(j.model||'AI model')+' ready via '+(j.provider||'server')+'.':'Backend is online, but no AI provider is configured yet.';}catch(e){el.textContent='AI is not connected yet. Open this app through its deployed Node server; a local HTML file cannot call the secure backend. '+e.message;}}
function aiPrompt(){const lang=document.getElementById('crLang').value;return {kind:document.getElementById('aiKind').value,language:lang,topic:document.getElementById('crTopic').selectedOptions[0].text,headline:document.getElementById('crHeadline').value,body:document.getElementById('crBody').value,cta:document.getElementById('crCta').value,footer:document.getElementById('crFooter').value,brief:document.getElementById('aiBrief').value};}
async function generateWithAI(){const btn=document.getElementById('aiGenerateBtn'),status=document.getElementById('aiStatus'),out=document.getElementById('aiResult');btn.disabled=true;btn.textContent='Generating…';status.textContent='Sending your creative brief to the AI service…';out.style.display='none';try{const r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(aiPrompt())});const j=await r.json();if(!r.ok)throw new Error(j.error||'AI generation failed');latestAIText=j.text||'';if(!latestAIText)throw new Error('The AI returned an empty response.');let data=null;try{const clean=latestAIText.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');data=JSON.parse(clean);}catch(_){}if(data){if(data.headline)document.getElementById('crHeadline').value=data.headline;if(data.body)document.getElementById('crBody').value=data.body;if(data.cta)document.getElementById('crCta').value=data.cta;if(data.caption)document.getElementById('ccopy').value=data.caption;if(data.reel_script){lastReel=data.reel_script;document.getElementById('reelOutput').textContent=data.reel_script;}if(data.kind==='poster'||document.getElementById('aiKind').value!=='reel')makePoster();out.textContent=[data.headline&&'HEADLINE: '+data.headline,data.body&&'MESSAGE: '+data.body,data.cta&&'CALL TO ACTION: '+data.cta,data.caption&&'CAPTION: '+data.caption,data.hashtags&&'HASHTAGS: '+data.hashtags,data.visual_direction&&'AI ART DIRECTION: '+data.visual_direction,data.reel_script&&'REEL SCRIPT:\n'+data.reel_script].filter(Boolean).join('\n\n')||latestAIText;}else{out.textContent=latestAIText;}out.style.display='block';document.getElementById('aiCopyBtn').disabled=false;document.getElementById('aiSaveBtn').disabled=false;status.textContent='AI draft generated. Review and fact-check before publishing; no content was posted or sent.';}catch(e){status.textContent='Could not generate: '+e.message+' Your brief is unchanged, so you can press Generate again.';}finally{btn.disabled=false;btn.textContent='Generate with AI';}}
function copyAIResult(){if(latestAIText)copyText(latestAIText)}
function saveAIResult(){if(!latestAIText)return;let a=get('creative');a.unshift({id:Date.now(),topic:$('crTopic').value,lang:$('crLang').value,ai:true,aiResult:latestAIText,createdAt:new Date().toISOString()});set('creative',a);alert('AI result saved in this browser. Include it in your next JSON backup.');}

